 document.body.append(dialog);$('libraryDialog').prepend(launch);
 let lesson=null,context=null,tab='editor',draft=[],selected=new Set(),undo=[],redo=[],currentAttempt=null,reviewQueue=[],reviewIndex=0,vocabEditing=null,recorder=null,stream=null,chunks=[],recordBlob=null,recordUrl=null,recordTimer=null,recordStarted=0,recordScope=null,recordingGeneration=0,recordURLs=[];
 const status=text=>{$('studyStatus').textContent=text;};
