 $('studyPlayPause').onclick=guard(()=>app.studyTransport('toggle'));$('studyTimeline').oninput=guard(()=>app.studyTransport('seek',Number($('studyTimeline').value)));$('studySpeed').onchange=guard(()=>app.studyTransport('speed',Number($('studySpeed').value)));
 setInterval(()=>{if(!dialog.open)return;const state=app.studyContext();$('studyTimeline').max=state.duration||0;if(document.activeElement!==$('studyTimeline'))$('studyTimeline').value=state.position||0;$('studyClock').textContent=(state.position||0).toFixed(1)+' / '+(state.duration||0).toFixed(1)+' s';},200);
 const base64=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});
 const decode=(s,type)=>new Blob([Uint8Array.from(atob(s),c=>c.charCodeAt(0))],{type});
 function lessonRequired(){if(!lesson)throw Error('Mở một bài nghe trong thư viện trước.');return lesson;}
